export const getPingUrl = () => {




  return `/api/v1/ping`
}

export const ping = async (pingRequest: NonReadonly<PingRequest>, options?: RequestInit): Promise<pingResponse> => {

  return customInstance<pingResponse>(getPingUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      pingRequest,)
  }
);}




export const getPingMutationOptions = <TError = ErrorType<ErrorModel>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof ping>>, TError,{data: BodyType<NonReadonly<PingRequest>>}, TContext>, request?: SecondParameter<typeof customInstance>}
): UseMutationOptions<Awaited<ReturnType<typeof ping>>, TError,{data: BodyType<NonReadonly<PingRequest>>}, TContext> => {

const mutationKey = ['ping'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof ping>>, {data: BodyType<NonReadonly<PingRequest>>}> = (props) => {
          const {data} = props ?? {};

          return  ping(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type PingMutationResult = NonNullable<Awaited<ReturnType<typeof ping>>>
    export type PingMutationBody = BodyType<NonReadonly<PingRequest>>
    export type PingMutationError = ErrorType<ErrorModel>

    /**
 * @summary Echo a message
 */
export const usePing = <TError = ErrorType<ErrorModel>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof ping>>, TError,{data: BodyType<NonReadonly<PingRequest>>}, TContext>, request?: SecondParameter<typeof customInstance>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof ping>>,
        TError,
        {data: BodyType<NonReadonly<PingRequest>>},
        TContext
      > => {
      return useMutation(getPingMutationOptions(options), queryClient);
    }

